contract.code:
Thread   = { threadId, blockId, openedBy, body, replies: Int, status: 'open' | 'resolved' }
Decision = { threadId, blockId, by, at, decision }
PlanView = { threads: Thread[], decisions: Decision[], version: Int }
CommandEnvelope = { type: 'OpenThread' | 'Reply' | 'ResolveThread', data: Record<string, unknown>, by: ParticipantId }

route(history: readonly StoredEvent[], command: Command, ctx: Ctx): DomainEvent[] | Rejection
project(events: readonly StoredEvent[]): PlanView
class CommandRejected { reason }      class InvalidCommand { type, message }

export class PlanRoom extends DurableObject<Env> {
  dispatch(command: Command, enabledFlags: string[]): { events: StoredEvent[] } | Rejection;
  events(): StoredEvent[];
  read(): PlanView;
  version(): number;
  fetch(request: Request): Promise<Response>;   // WebSocket upgrade, then { type: 'hello', version }
}
// after each append, every socket gets { type: 'events', events }

PlanRooms: dispatch(planId, command, flags) · events(planId) · read(planId) · ping()
Commands:  dispatch(planId, body: unknown): Effect<StoredEvent[], InvalidCommand | CommandRejected>
// each has layerTest: the same decider over an in-memory log

components.css:
.thread { border: 1px solid var(--line); border-radius: var(--radius-lg); padding: 20px; max-width: 600px; font-family: var(--font); }
.meta { margin: 0; font-size: 12px; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.body { margin: 6px 0 0; font-size: 16px; font-weight: 500; }
form { display: flex; gap: 8px; margin-top: 12px; }
input { flex: 1; font: inherit; font-size: 14px; padding: 8px 12px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); }
button { font: inherit; font-size: 14px; font-weight: 600; padding: 8px 14px; border: 0; border-radius: var(--radius-md); background: var(--accent); color: #fff; }
.alert { max-width: 600px; margin: 0 0 12px; border: 1px solid var(--alertLine); background: var(--alert); color: var(--warn); border-radius: var(--radius-md); padding: 8px 12px; font-size: 14px; }
.decided { margin: 12px 0 0; font-size: 14px; }
.decided .tag { color: var(--ok); font-weight: 600; }
.decided .who { color: var(--muted); }

.page { max-width: 640px; font-family: var(--font); }
header { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; }
.kicker { margin: 0; font-size: 12px; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
h1 { margin: 0; font-size: 30px; font-weight: 600; }
label { display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--muted); }
label input { width: 112px; font: inherit; font-size: 14px; padding: 4px 8px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); }
.counts { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0 0; font-size: 13px; color: var(--muted); }
.counts span { border: 1px solid var(--line); border-radius: 999px; padding: 1px 9px; }
.counts .live { color: var(--ok); border-color: var(--ok); }
.empty { margin: 24px 0 0; font-size: 14px; color: var(--muted); }
.open { margin-top: 24px; border: 1px dashed var(--line); border-radius: var(--radius-lg); padding: 20px; }
.open p { margin: 0; }
.open .title { font-size: 14px; font-weight: 600; }
.open .hint { margin-top: 4px; font-size: 12px; color: var(--muted); }
.row { display: flex; gap: 8px; margin-top: 8px; }
.row input { flex: 1; font: inherit; font-size: 14px; padding: 8px 12px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); }
.row input.block { flex: 0 0 120px; }
.row button { font: inherit; font-size: 14px; font-weight: 600; padding: 8px 14px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); }
